arguments.content:
/* ClipCast — Global Styles */
:root {
  --primary: #1868DB;
  --primary-dark: #1254B5;
  --primary-light: #E8F0FE;
  --accent: #FF613D;
  --accent-dark: #E5502E;
  --dark: #292A2E;
  --dark-light: #3D3E42;
  --gray-900: #1A1B1E;
  --gray-800: #3D3E42;
  --gray-700: #56575C;
  --gray-600: #6E7076;
  --gray-500: #87898F;
  --gray-400: #A0A2A8;
  --gray-300: #B9BBC1;
  --gray-200: #D2D3D9;
  --gray-100: #EBEBF0;
  --gray-50: #F5F5F8;
  --white: #FFFFFF;
  --green: #14B866;
  --purple: #7C3AED;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.1), 0 4px 12px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.12), 0 8px 20px rgba(0,0,0,0.06);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font);
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; transition: color var(--transition); }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul, ol { list-style: none; }
input { font-family: inherit; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-wide {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 { line-height: 1.2; font-weight: 700; }
h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; }
h3 { font-size: 1.75rem; }
h4 { font-size: 1.25rem; }
p { color: var(--gray-700); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 1rem;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.btn-accent {
  background: var(--accent);
  color: var(--white);
}
.btn-accent:hover { background: var(--accent-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 2px solid var(--gray-200);
}
.btn-outline:hover { border-color: var(--primary); color: var(--primary); }

.btn-white {
  background: var(--white);
  color: var(--primary);
}
.btn-white:hover { background: var(--gray-50); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.btn-dark {
  background: var(--dark);
  color: var(--white);
}
.btn-dark:hover { background: var(--gray-800); transform: translateY(-1px); }

.btn-sm { padding: 10px 20px; font-size: 0.875rem; }
.btn-lg { padding: 18px 36px; font-size: 1.125rem; }

.btn-ghost {
  background: transparent;
  color: var(--primary);
  padding: 10px 16px;
}
.btn-ghost:hover { background: var(--primary-light); }

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-100);
  padding: 0 24px;
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--dark);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo svg { width: 32px; height: 32px; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-weight: 500;
  color: var(--gray-700);
  font-size: 0.9375rem;
  transition: color var(--transition);
}

.nav-links a:hover { color: var(--primary); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.nav-mobile-toggle span {
  width: 24px;
  height: 2px;
  background: var(--dark);
  border-radius: 2px;
  transition: var(--transition);
}

/* Sections */
.section {
  padding: 100px 0;
}

.section-sm {
  padding: 60px 0;
}

.section-gray {
  background: var(--gray-50);
}

.section-dark {
  background: var(--dark);
  color: var(--white);
}

.section-dark p { color: var(--gray-300); }

.section-gradient {
  background: linear-gradient(135deg, #1868DB 0%, #7C3AED 100%);
  color: var(--white);
}

.section-gradient p { color: rgba(255,255,255,0.85); }

.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 60px;
}

.section-header h2 { margin-bottom: 16px; }
.section-header p { font-size: 1.125rem; color: var(--gray-600); }

.label {
  display: inline-flex;
  align-items: center;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.label-primary { background: var(--primary-light); color: var(--primary); }
.label-accent { background: #FFF0EC; color: var(--accent); }
.label-green { background: #E6F9EF; color: var(--green); }
.label-purple { background: #F3EAFF; color: var(--purple); }

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero h1 {
  margin-bottom: 24px;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}

.hero p {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-visual {
  margin-top: 60px;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  background: var(--gray-100);
  aspect-ratio: 16/9;
  max-width: 960px;
  margin-left: auto;
  margin-right: auto;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-visual-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  color: var(--gray-400);
}

.hero-visual-placeholder svg { width: 64px; height: 64px; opacity: 0.5; }

/* Logo Bar */
.logo-bar {
  padding: 40px 0;
  border-top: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
}

.logo-bar p {
  text-align: center;
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
  font-weight: 500;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-bar-logos span {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-400);
  letter-spacing: -0.01em;
}

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: all var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}

.card-icon-primary { background: var(--primary-light); color: var(--primary); }
.card-icon-accent { background: #FFF0EC; color: var(--accent); }
.card-icon-green { background: #E6F9EF; color: var(--green); }
.card-icon-purple { background: #F3EAFF; color: var(--purple); }

.card h4 { margin-bottom: 8px; }
.card p { font-size: 0.9375rem; }

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; align-items: center; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }

/* Feature Split */
.feature-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-split-content h2 { margin-bottom: 16px; }
.feature-split-content p { margin-bottom: 24px; }

.feature-split-visual {
  border-radius: var(--radius-xl);
  background: var(--gray-50);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.feature-split-visual-placeholder {
  color: var(--gray-400);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.feature-split.reverse { direction: rtl; }
.feature-split.reverse > * { direction: ltr; }

/* Feature List Items */
.feature-list { display: flex; flex-direction: column; gap: 24px; }

.feature-list-item {
  display: flex;
  gap: 16px;
}

.feature-list-item .icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-list-item h4 { margin-bottom: 4px; font-size: 1.125rem; }
.feature-list-item p { font-size: 0.9375rem; }

/* Use Cases */
.use-case-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-100);
  text-align: center;
  transition: all var(--transition);
}

.use-case-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
  border-color: var(--primary);
}

.use-case-card .icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.5rem;
}

.use-case-card h4 { margin-bottom: 8px; }
.use-case-card p { font-size: 0.875rem; }

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item h3 {
  font-size: 3.5rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.stat-item p { font-size: 1rem; color: var(--gray-600); }

/* Testimonials */
.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-100);
}

.testimonial-card blockquote {
  font-size: 1rem;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-card .author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-card .author-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  font-weight: 700;
  font-size: 0.875rem;
}

.testimonial-card .author-info strong { display: block; font-size: 0.9375rem; color: var(--dark); }
.testimonial-card .author-info span { font-size: 0.8125rem; color: var(--gray-500); }

/* Testimonial Featured */
.testimonial-featured {
  background: var(--gray-50);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-featured blockquote {
  font-size: 1.25rem;
  color: var(--dark);
  line-height: 1.7;
  margin-bottom: 24px;
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.pricing-toggle span { font-weight: 500; color: var(--gray-600); }
.pricing-toggle span.active { color: var(--dark); font-weight: 600; }

.toggle-switch {
  width: 52px;
  height: 28px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: background var(--transition);
}

.toggle-switch.active { background: var(--primary); }

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--white);
  top: 3px;
  left: 3px;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after { transform: translateX(24px); }

.save-badge {
  background: var(--green);
  color: var(--white);
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 2px solid var(--gray-100);
  position: relative;
  transition: all var(--transition);
}

.pricing-card:hover { box-shadow: var(--shadow-lg); }

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
}

.pricing-card .popular-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  white-space: nowrap;
}

.pricing-card h4 { font-size: 1.25rem; margin-bottom: 4px; }
.pricing-card .price { font-size: 2.5rem; font-weight: 800; margin: 16px 0 4px; }
.pricing-card .price-period { font-size: 0.875rem; color: var(--gray-500); margin-bottom: 24px; }
.pricing-card .features-list { margin-bottom: 24px; }

.pricing-card .features-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--gray-700);
}

.pricing-card .features-list li svg {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  color: var(--green);
  margin-top: 2px;
}

.pricing-card .btn { width: 100%; }

/* Team Size Slider */
.team-slider {
  max-width: 600px;
  margin: 0 auto 48px;
  text-align: center;
}

.team-slider label {
  display: block;
  font-weight: 600;
  margin-bottom: 16px;
  font-size: 1.125rem;
}

.team-slider input[type="range"] {
  width: 100%;
  -webkit-appearance: none;
  height: 8px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  outline: none;
}

.team-slider input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  box-shadow: var(--shadow-md);
}

.team-slider input[type="range"]::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  border: none;
  box-shadow: var(--shadow-md);
}

.team-slider .slider-value {
  margin-top: 8px;
  font-weight: 600;
  color: var(--primary);
  font-size: 1.25rem;
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin-top: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.comparison-table thead th {
  padding: 16px 20px;
  text-align: center;
  font-weight: 700;
  border-bottom: 2px solid var(--gray-200);
  background: var(--gray-50);
  position: sticky;
  top: 72px;
}

.comparison-table thead th:first-child { text-align: left; }
.comparison-table thead th.highlight { color: var(--primary); background: var(--primary-light); }

.comparison-table tbody td {
  padding: 14px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
  color: var(--gray-700);
}

.comparison-table tbody td:first-child {
  text-align: left;
  font-weight: 500;
  color: var(--dark);
}

.comparison-table tbody td.highlight { background: rgba(24,104,219,0.03); }

.comparison-table .check {
  color: var(--green);
  font-weight: 700;
  font-size: 1.125rem;
}

.comparison-table .dash {
  color: var(--gray-300);
}

.comparison-table-toggle {
  text-align: center;
  margin-top: 24px;
}

/* FAQ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-100);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px 0;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--dark);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: color var(--transition);
}

.faq-question:hover { color: var(--primary); }

.faq-question svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
}

.faq-item.active .faq-question svg { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p { font-size: 0.9375rem; color: var(--gray-600); line-height: 1.7; }

/* AI Features */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.ai-feature-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 500;
  transition: all var(--transition);
}

.ai-feature-item:hover { box-shadow: var(--shadow-sm); border-color: var(--primary); }

.ai-feature-item .new-tag {
  background: var(--accent);
  color: var(--white);
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
}

/* Blog Cards */
.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-100);
  transition: all var(--transition);
}

.blog-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }

.blog-card-image {
  aspect-ratio: 16/9;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
}

.blog-card-content { padding: 24px; }
.blog-card-content h4 { margin-bottom: 8px; font-size: 1.125rem; }
.blog-card-content p { font-size: 0.875rem; }
.blog-card-content .read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.875rem;
}

/* CTA Banner */
.cta-banner {
  text-align: center;
  padding: 80px 0;
}

.cta-banner h2 { margin-bottom: 16px; color: var(--white); }
.cta-banner p { margin-bottom: 32px; }
.cta-banner .btn { font-size: 1.125rem; }

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-300);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h5 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.875rem;
  color: var(--gray-400);
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid var(--gray-800);
  padding-top: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
